<script setup>
import { Sparkles, Send, MessageSquare, ChevronRight } from 'lucide-vue-next'
import { useAppState } from '../state/appState'
const { USER, chat, chatInput, chatBusy, chatBox, sendChat }=useAppState()
const suggestions=['Explain genes simply','What is DNA?','How do mutations work?']; const questions=['Why are genes important?','Explain DNA like I’m 10','What is a mutation?','How does transcription work?']
function ask(q){chatInput.value=q; sendChat()}
</script>
<template><section class="page ai-page"><div class="page-head"><span class="eyebrow green">YOUR STUDY PARTNER</span><h1>AI Tutor</h1><p>Ask questions, get explanations, and work through difficult concepts.</p></div><div class="ai-layout"><div class="chat-panel panel"><div class="chat-head"><div class="ai-avatar"><Sparkles :size="18"/></div><div><b>AI Tutor</b><small>Online · ready to help</small></div><span class="online"></span></div><div ref="chatBox" class="chat-messages"><div v-for="m in chat" :key="m.id" class="message" :class="m.role"><div class="message-avatar">{{m.role==='ai'?'AI':USER.name[0]}}</div><div><div class="bubble">{{m.content}}</div><small>{{m.time}}</small></div></div><div v-if="chatBusy" class="message ai"><div class="message-avatar">AI</div><div class="bubble typing"><i></i><i></i><i></i></div></div></div><div class="suggestions"><button v-for="q in suggestions" :key="q" @click="ask(q)">{{q}}</button></div><form class="chat-input" @submit.prevent="sendChat"><input v-model="chatInput" placeholder="Ask your tutor anything…"><button :disabled="!chatInput.trim()"><Send :size="17"/></button></form></div><aside class="side-stack"><div class="panel"><h3>Try asking</h3><div v-for="q in questions" :key="q" class="question-link" @click="ask(q)"><MessageSquare :size="14"/><span>{{q}}</span><ChevronRight :size="13"/></div></div><div class="panel ai-note"><Sparkles :size="18"/><b>Tip</b><p>Ask follow-up questions whenever an explanation isn't clear. Your tutor can explain the same concept in different ways.</p></div></aside></div></section></template>
